SELECT page, CASE WHEN duration_sec >= 453 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, AVG(duration_sec) FILTER (WHERE page = '/cart') AS cart_avg_duration_sec, COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) AS purchase_count, AVG(duration_sec) AS avg_duration_sec, GROUPING_ID() AS gid FROM web_events GROUP BY ROLLUP (page, CASE WHEN duration_sec >= 453 THEN 'LARGE' ELSE 'SMALL' END) HAVING cart_avg_duration_sec > 0;
